export const meta = {
  name: 'review-remaining-prs',
  description: 'Adversarial review + blocker-fix for PRs #109 (issue 89), #108 (issue 91), #110 (issue 97) whose review stage died in the main run',
  phases: [{ title: 'Review & fix', detail: 'review each PR, fix blockers if any', model: 'opus' }],
}

const IMPL_SCHEMA = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['ok', 'draft', 'blocked'] },
    pr: { type: 'number' },
    branch: { type: 'string' },
    notes: { type: 'string', maxLength: 600 },
  },
  required: ['status', 'notes'],
}

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    blockers: {
      type: 'array', maxItems: 8,
      items: {
        type: 'object',
        properties: { file: { type: 'string' }, problem: { type: 'string', maxLength: 300 } },
        required: ['problem'],
      },
    },
    nits: { type: 'array', maxItems: 8, items: { type: 'string', maxLength: 200 } },
  },
  required: ['blockers'],
}

const TARGETS = [
  { n: 89, pr: 109, title: 'rendering: presentation scaling policy',
    premises: 'MonoDreams/rendering/docs/premises.md',
    note: 'This PR is a DRAFT stacked on issue-88 (PR #100) — its base branch is issue-88 and it must stay a draft; the stacking itself is NOT a blocker. Review only the delta vs issue-88 (the PR diff already shows exactly that).' },
  { n: 91, pr: 108, title: 'debug: RenderTarget-resolution screenshots + MONODREAMS_KEEP_AWAKE',
    premises: 'MonoDreams/debug/docs/premises.md, MonoDreams/rendering/docs/premises.md',
    note: 'Check especially: default MONODREAMS_SCREENSHOT_TARGET=window preserves byte-compatible behavior; named-target capture reads the RenderTarget at fixed resolution; KEEP_AWAKE is macOS-only with graceful no-op elsewhere.' },
  { n: 97, pr: 110, title: 'docs: pointer double-dispatch premise + message-driven audio example',
    premises: 'MonoDreams/ui/docs/premises.md, MonoDreams/audio/docs/premises.md, MonoDreams/audio/docs/overview.md',
    note: 'Docs-only PR. Check the premises follow the exact Why/Breaks/Tests/Depends-on format, the described arbitration pattern matches how UIFocusSystem actually works in code, and the AudioCueSystem example compiles conceptually against the real audio module API (message names, PlaySoundRequest shape).' },
]

function reviewPrompt(c) {
  return [
    'You are an adversarial code reviewer for PR #' + c.pr + ' (issue #' + c.n + ', "' + c.title + '") in roo-oliv/monodreams.',
    'Work READ-ONLY from the repo root: never checkout branches, never modify files.',
    '',
    "1. Run 'gh pr view " + c.pr + "' and 'gh pr diff " + c.pr + "'; 'gh issue view " + c.n + "' for the acceptance criteria.",
    '2. Read docs/CORE_TENETS.md and: ' + c.premises,
    '3. ' + c.note,
    '4. Hunt hard for: violated premises/tenets (ECS purity, one-way-to-do-things, rendering pipeline contracts, module dependency arrows), unmet acceptance criteria from the issue, correctness bugs with a concrete failure scenario, missing or vacuous tests, docs the issue required but the PR skipped. Ignore pure style. A dependency PR that is not merged yet (stacked branches) is NOT a blocker.',
    "5. Post ONE consolidated review comment on the PR via 'gh pr comment " + c.pr + " --body ...' listing Blockers and Non-blockers (or LGTM if clean).",
    '',
    'Return via StructuredOutput: blockers (ONLY defects that must be fixed before merge; each with file and problem <=300 chars) and nits. Be skeptical but honest — do not invent blockers to seem thorough.',
  ].join('\n')
}

function fixPrompt(c, blockers) {
  const list = blockers.map(function (b, i) { return (i + 1) + '. ' + (b.file ? b.file + ': ' : '') + b.problem }).join('\n')
  return [
    'You are fixing review blockers on PR #' + c.pr + ' (issue #' + c.n + ') of roo-oliv/monodreams. You are in an ISOLATED GIT WORKTREE.',
    '',
    "1. Run 'git fetch origin && git checkout -B issue-" + c.n + " origin/issue-" + c.n + "'.",
    '2. Address ONLY these blockers — no scope creep:',
    list,
    '3. Context: docs/CORE_TENETS.md, docs/agents/skills-config.md, and: ' + c.premises,
    "4. Build core FIRST (dotnet build MonoDreams/MonoDreams.csproj). Verify with the repo's configured verify command; ALWAYS pass '-m:1 -p:RestoreDisableParallel=true' to dotnet build/test; retry once on a restore flake. Never push to main, never force-push, do not merge or un-draft the PR.",
    "5. Verify green, commit per repo conventions, 'git push origin issue-" + c.n + "', post a short PR comment stating what was fixed, then 'git checkout --detach'.",
    'If a blocker is actually wrong (the reviewer misread the code), do not change code for it — explain why in the PR comment and in notes.',
    '',
    'Return via StructuredOutput: status (ok|draft|blocked), pr, branch, notes (<=600 chars).',
  ].join('\n')
}

async function runTarget(c) {
  const rev = await agent(reviewPrompt(c), { label: 'review#' + c.n, phase: 'Review & fix', model: 'opus', schema: REVIEW_SCHEMA })
  if (!rev) return { issue: c.n, pr: c.pr, status: 'review-failed' }
  const blockers = (rev.blockers || []).filter(Boolean)
  if (blockers.length === 0) return { issue: c.n, pr: c.pr, status: 'review clean', nits: (rev.nits || []).length }
  const fix = await agent(fixPrompt(c, blockers), { label: 'fix#' + c.n, phase: 'Review & fix', model: 'opus', isolation: 'worktree', schema: IMPL_SCHEMA })
  if (!fix) return { issue: c.n, pr: c.pr, status: 'blockers-unfixed', blockers: blockers.length }
  return { issue: c.n, pr: c.pr, status: fix.status + ' (fixed ' + blockers.length + ' blockers)', notes: fix.notes }
}

phase('Review & fix')
log('Reviewing PRs #109 (issue 89), #108 (issue 91), #110 (issue 97)')
const results = await parallel(TARGETS.map(function (c) { return function () { return runTarget(c) } }))
return { results: results.filter(Boolean) }

